const participants = $('Fetch NDIS Participants').all().map(i => i.json);
const priceGuide = $('Fetch NDIS Price Guide').all().map(i => i.json);
const invoices = $('Split Out Invoices').all().map(i => i.json);

const priceMap = {};
for (const p of priceGuide) { priceMap[String(p.support_item_number).trim()] = p; }
const byPatient = {};
for (const p of participants) { byPatient[String(p.patient_id).trim()] = p; }

// Claims already in the ledger: anything past failed_validation is final or already batched - never re-process
const existingClaims = {};
for (const r of $('Fetch Existing Claims').all()) { existingClaims[String(r.json.claim_reference).trim()] = String(r.json.status || ''); }

const batchId = 'BATCH-' + $today.toFormat('yyyyLLdd');
const seen = {};
const out = [];
const inputs = $input.all();

for (let idx = 0; idx < inputs.length; idx++) {
  const resp = inputs[idx].json;
  const inv = invoices[idx] || resp;

  // Cliniko references the patient as a link URL; fall back to flat fields for other PMSs
  let patientId = String(inv.patient_id ?? inv.patientId ?? '').trim();
  if (!patientId && inv.patient && inv.patient.id) patientId = String(inv.patient.id);
  if (!patientId && inv.patient && inv.patient.links && inv.patient.links.self) {
    const m = String(inv.patient.links.self).match(/patients\/(\d+)/);
    if (m) patientId = m[1];
  }

  const invoiceNumber = String(inv.invoice_number ?? inv.number ?? '').trim();
  const serviceDate = String(inv.service_date ?? inv.issue_date ?? '').slice(0, 10);

  let lines = Array.isArray(resp.invoice_items) ? resp.invoice_items : (Array.isArray(inv.items) ? inv.items : []);
  if (!lines.length) lines = [inv];

  for (const line of lines) {
    let supportItem = String(line.support_item_number ?? line.item_code ?? line.code ?? '').trim();
    if (!supportItem) {
      const m2 = String((line.name ?? '') + ' ' + (line.description ?? '')).match(/\d{2}_\d{3}_\d{4}_\d_\d/);
      if (m2) supportItem = m2[0];
    }

    // Lines coded for another funder (e.g. workers comp WCP001) are handled by that funder's workflow
    if (supportItem && !priceMap[supportItem] && !/^[0-9]{2}_/.test(supportItem)) continue;

    const quantity = Number(line.quantity ?? 1);
    const unitPrice = Number(line.unit_price ?? line.price ?? inv.total_amount ?? 0);
    const errors = [];

    const participant = byPatient[patientId];
    if (!participant) errors.push('No NDIS participant record for patient id "' + patientId + '"');

    const ndisNumber = participant ? String(participant.ndis_number ?? '').trim() : '';
    if (participant && !/^43\d{7}$/.test(ndisNumber)) errors.push('NDIS number "' + ndisNumber + '" is not a valid 9-digit number starting with 43');

    const planType = participant ? String(participant.plan_type ?? '').toLowerCase().trim() : '';
    if (participant && !['agency', 'plan', 'self'].includes(planType)) errors.push('Unknown plan management type "' + planType + '" (expected agency, plan or self)');

    if (participant && serviceDate) {
      const ps = String(participant.plan_start ?? '').slice(0, 10);
      const pe = String(participant.plan_end ?? '').slice(0, 10);
      if (ps && serviceDate < ps) errors.push('Service date ' + serviceDate + ' is before plan start ' + ps);
      if (pe && serviceDate > pe) errors.push('Service date ' + serviceDate + ' is after plan end ' + pe + ' (plan may have expired)');
    }

    const priceRow = priceMap[supportItem];
    if (!supportItem) errors.push('Missing NDIS support item number (set it as the billable item code, or include e.g. 15_055_0128_1_3 in the item name)');
    else if (!priceRow) errors.push('Support item "' + supportItem + '" not found in price guide table');
    else if (unitPrice > Number(priceRow.price_limit)) errors.push('Unit price $' + unitPrice.toFixed(2) + ' exceeds price limit $' + Number(priceRow.price_limit).toFixed(2) + ' for ' + supportItem);

    if (!(quantity > 0)) errors.push('Quantity must be greater than zero');
    if (!serviceDate) errors.push('Missing service date');

    const claimRef = (invoiceNumber || 'NOINV') + '-' + (supportItem || 'NOITEM') + '-' + serviceDate;

    // Status protection: skip claims already batched (validated) or final (paid/rejected).
    // Only failed_validation claims are re-processed, so fixes flow through on the next run.
    const prior = existingClaims[claimRef];
    if (prior && prior !== 'failed_validation') continue;

    if (seen[claimRef]) errors.push('Duplicate claim line in this batch: ' + claimRef);
    seen[claimRef] = true;

    out.push({ json: {
      claim_reference: claimRef,
      invoice_number: invoiceNumber,
      patient_id: patientId,
      ndis_number: ndisNumber,
      participant_name: participant ? ((participant.first_name || '') + ' ' + (participant.last_name || '')).trim() : '',
      support_item_number: supportItem,
      support_item_name: priceRow ? priceRow.support_item_name : '',
      service_date: serviceDate,
      quantity: quantity,
      unit_price: unitPrice,
      total: Math.round(quantity * unitPrice * 100) / 100,
      gst_code: priceRow && priceRow.gst_code ? priceRow.gst_code : 'P2',
      plan_type: planType,
      plan_manager_email: participant ? (participant.plan_manager_email || '') : '',
      participant_email: participant ? (participant.participant_email || '') : '',
      status: errors.length ? 'failed_validation' : 'validated',
      validation_errors: errors.join('; '),
      batch_id: batchId,
      funder: 'ndis'
    }});
  }
}
return out;

const failed = $('Validate NDIS Claims').all().map(i => i.json).filter(c => c.status === 'failed_validation');
let rows = '';
for (const c of failed) {
  rows += '<tr><td>' + c.claim_reference + '</td><td>' + (c.participant_name || 'Unknown') + '</td><td>' + c.validation_errors + '</td></tr>';
}
const html = '<h2>NDIS claims failing validation (' + failed.length + ')</h2>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">' +
  '<tr><th>Claim</th><th>Participant</th><th>Problems</th></tr>' + rows + '</table>' +
  '<p>Fix these in the practice management system, or in the ndis_participants / ndis_price_guide data tables in n8n, then re-run the workflow. Nothing invalid was included in a claim batch.</p>';
return [{ json: { html: html, count: failed.length } }];
